window.PROJECT_H_SCENES["end01h"]=[
{"rowNumber":1,"id":"end01h.mes#1625","kind":"text","speaker":"시에","english":"","japanese":"紫衣「いつまで待たせるつもり？　早くしなさいよ」","korean":"언제까지 기다리게 할 거야? 빨리해.","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":2,"id":"end01h.mes#1755","kind":"text","speaker":"나레이션","english":"","japanese":"先に裸になった紫衣に急かされつつも、俺は二人の肢体をまじまじと眺めながらゆっくりと衣服を脱ぎ捨てていく。","korean":"먼저 옷을 벗은 시에가 재촉했지만 나는 두 사람의 몸을 한참 바라보면서 천천히 옷을 벗었다.","recordingScript":"","memo":"음성 1","voice":"","phaseId":"end01h-P1"},
{"rowNumber":3,"id":"end01h.mes#2059","kind":"text","speaker":"안리","english":"","japanese":"杏里「ともくん……今日はどうしますか？」","korean":"토모 군…… 오늘은 어떻게 할까요?","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":4,"id":"end01h.mes#2181","kind":"text","speaker":"토모키","english":"","japanese":"大樹「それじゃ……まずは二人にオチンチンを舐めてもらおうかな？」","korean":"그럼…… 먼저 둘이 자지를 핥아 줄래?","recordingScript":"","memo":"음성 3","voice":"","phaseId":"end01h-P1"},
{"rowNumber":5,"id":"end01h.mes#2445","kind":"text","speaker":"안리","english":"","japanese":"杏里「はい、ともくん」","korean":"네, 토모 군.","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":6,"id":"end01h.mes#2477","kind":"text","speaker":"시에","english":"","japanese":"紫衣「ええ、わかったわ」","korean":"그래, 알았어.","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":7,"id":"end01h.mes#2708","kind":"text","speaker":"나레이션","english":"","japanese":"既に硬く勃起したペニスを彼女らの前へ突き出すと……二人は吸い寄せられるように、赤く濡れた舌を亀頭へ押しつけていく。","korean":"이미 단단하게 선 성기를 둘 앞에 내밀었다…… 두 사람은 끌리듯 붉고 젖은 혀를 귀두에 댔다.","recordingScript":"","memo":"음성 5","voice":"","phaseId":"end01h-P1"},
{"rowNumber":8,"id":"end01h.mes#3159","kind":"text","speaker":"시에","english":"","japanese":"紫衣「れろっ……ちゅっ……ふぅ……あむっ……ちゅばっ……ちゅぅ」","korean":"핥짝…… 쪽…… 후우…… 앙…… 쪽…… 쮸우.","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":9,"id":"end01h.mes#3423","kind":"text","speaker":"안리","english":"","japanese":"杏里「はむっ……ちゅっ、ちゅぅ……れろっ、れろっ……んんっ……」","korean":"앙…… 쪽, 쮸우…… 핥짝, 핥짝…… 으응……","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":10,"id":"end01h.mes#3569","kind":"text","speaker":"나레이션","english":"","japanese":"瞳をトロンと潤ませた、二人の熱い舌とこそばゆい鼻息が絡み合う……","korean":"눈이 촉촉하게 풀린 두 사람의 뜨거운 혀와 간지러운 콧김이 뒤섞였다……","recordingScript":"","memo":"음성 8","voice":"","phaseId":"end01h-P1"},
{"rowNumber":11,"id":"end01h.mes#3715","kind":"text","speaker":"나레이션","english":"","japanese":"まるで肉棒を介しキスをするように、二人は丁重に亀頭を舐め回していく。","korean":"성기를 사이에 두고 입을 맞추듯 둘은 정성스럽게 귀두를 핥았다.","recordingScript":"","memo":"음성 9","voice":"","phaseId":"end01h-P1"},
{"rowNumber":12,"id":"end01h.mes#3865","kind":"text","speaker":"나레이션","english":"","japanese":"３人でするようになってから、ノーマルだと思っていた杏里がすんなり紫衣へ身体を重ねた事が気になり質問をした所……","korean":"셋이 함께하기 시작한 뒤, 여자에게는 관심 없을 줄 알았던 안리가 자연스레 시에와 몸을 포갠 게 궁금해서 물어봤다……","recordingScript":"","memo":"음성 10","voice":"","phaseId":"end01h-P1"},
{"rowNumber":13,"id":"end01h.mes#4176","kind":"text","speaker":"나레이션","english":"","japanese":"杏里【ともくん一人が攻めだと、２倍疲れて大変じゃないですか】","korean":"안리【토모 군 혼자서 상대하면 두 배로 힘들잖아요.】","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":14,"id":"end01h.mes#4437","kind":"text","speaker":"나레이션","english":"","japanese":"杏里【それに折角一緒に愛されるわけですから……紫衣お姉様と一緒に感じたいんです】","korean":"안리【게다가 기왕 함께 사랑받는 거…… 시에 언니랑 같이 느끼고 싶어요.】","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":15,"id":"end01h.mes#4599","kind":"text","speaker":"나레이션","english":"","japanese":"という考えのもと、同性愛的な行為を受け入れたらしい。","korean":"그런 생각으로 여자끼리 몸을 섞는 일도 받아들인 모양이다.","recordingScript":"","memo":"음성 13","voice":"","phaseId":"end01h-P1"},
{"rowNumber":16,"id":"end01h.mes#4733","kind":"text","speaker":"토모키","english":"","japanese":"大樹（嫌がっているわけではないし……仲がいいのはいい事だよな……うん、うん）","korean":"싫어하는 것도 아니고…… 둘이 사이가 좋은 건 좋은 일이지…… 그래, 그래.","recordingScript":"","memo":"음성 14","voice":"","phaseId":"end01h-P1"},
{"rowNumber":17,"id":"end01h.mes#4891","kind":"text","speaker":"나레이션","english":"","japanese":"それに普段はお世辞にも仲睦まじいとは言い難い二人が……こうして肉欲にまみれる様は、眺めているだけでも興奮させてくれる。","korean":"평소에는 빈말로도 다정하다고 하기 어려운 두 사람이 이렇게 욕정에 빠진 모습을 보고 있으면 나도 흥분됐다.","recordingScript":"","memo":"음성 15","voice":"","phaseId":"end01h-P1"},
{"rowNumber":18,"id":"end01h.mes#5209","kind":"text","speaker":"시에","english":"","japanese":"紫衣「ちゅばっ……んふぅ……れろっ……あむっ……ちゅっ……れろっ、れろっ」","korean":"쪽…… 후우…… 핥짝…… 앙…… 쪽…… 핥짝, 핥짝.","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":19,"id":"end01h.mes#5483","kind":"text","speaker":"안리","english":"","japanese":"杏里「ぴちゃっ、ぴちゃっ……んふぅ……ちゅっ……はむっ……ちゅっ、ちゅうう」","korean":"찰박, 찰박…… 후우…… 쪽…… 앙…… 쪽, 쮸우우.","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":20,"id":"end01h.mes#5641","kind":"text","speaker":"나레이션","english":"","japanese":"まばゆいばかりの裸身を惜しげもなく晒す、美女達による愛の篭った奉仕……","korean":"눈부실 만큼 아름다운 두 사람이 알몸을 숨김없이 드러낸 채 정성껏 나를 기쁘게 해 줬다……","recordingScript":"","memo":"음성 18","voice":"","phaseId":"end01h-P1"},
{"rowNumber":21,"id":"end01h.mes#5793","kind":"text","speaker":"나레이션","english":"","japanese":"その甘美な刺激に、肉棒はその形をより赤黒く禍々しいものへと変貌させていく。","korean":"달콤한 자극에 성기는 갈수록 검붉고 위압적으로 부풀었다.","recordingScript":"","memo":"음성 19","voice":"","phaseId":"end01h-P1"},
{"rowNumber":22,"id":"end01h.mes#6204","kind":"text","speaker":"시에","english":"","japanese":"紫衣「ちゅぱっ……ふふ……びくびくし始めたわね……」","korean":"쪽…… 후후…… 움찔거리기 시작했네……","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":23,"id":"end01h.mes#6456","kind":"text","speaker":"안리","english":"","japanese":"杏里「……ともくん、気持ちいいですか？」","korean":"……토모 군, 기분 좋아요?","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":24,"id":"end01h.mes#6578","kind":"text","speaker":"토모키","english":"","japanese":"大樹「ああっ！　……凄く、いいぞ」","korean":"응! ……엄청, 좋아.","recordingScript":"","memo":"음성 22","voice":"","phaseId":"end01h-P1"},
{"rowNumber":25,"id":"end01h.mes#6812","kind":"text","speaker":"안리","english":"","japanese":"杏里「もっと、もっと……気持ちよくしてあげますね」","korean":"더, 더…… 기분 좋게 해 줄게요.","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":26,"id":"end01h.mes#7081","kind":"text","speaker":"나레이션","english":"","japanese":"二人は鏡合わせのように亀頭を唇で挟みこんでいく。","korean":"둘은 거울에 비친 것처럼 양편에서 입술로 귀두를 감쌌다.","recordingScript":"","memo":"음성 24","voice":"","phaseId":"end01h-P1"},
{"rowNumber":27,"id":"end01h.mes#7211","kind":"text","speaker":"나레이션","english":"","japanese":"そして重なり合う唇の中に収められた先端へ、両側から熱烈なキスの嵐を繰り出しはじめた。","korean":"포개진 입술 사이로 성기 끝을 머금고 양쪽에서 뜨겁게 입을 맞추기 시작했다.","recordingScript":"","memo":"음성 25","voice":"","phaseId":"end01h-P1"},
{"rowNumber":28,"id":"end01h.mes#7495","kind":"text","speaker":"시에","english":"","japanese":"紫衣「んふぅ……じゅるっ、ちゅっ、ちゅばっ！　ちゅっ、ちゅぅ……」","korean":"후우…… 후룩, 쪽, 쪽! 쪽, 쮸우……","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":29,"id":"end01h.mes#7761","kind":"text","speaker":"안리","english":"","japanese":"杏里「はむっ、はむっ……れろっ、れろれろっ……ちゅっ、ちゅううっ！」","korean":"앙, 앙…… 핥짝, 핥짝…… 쪽, 쮸우우!","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":30,"id":"end01h.mes#7911","kind":"text","speaker":"나레이션","english":"","japanese":"隙間なく押し付けられた唇の中にすっぽりと納まった亀頭。","korean":"빈틈없이 맞댄 입술 사이에 귀두가 쏙 들어갔다.","recordingScript":"","memo":"음성 28","voice":"","phaseId":"end01h-P1"},
{"rowNumber":31,"id":"end01h.mes#8047","kind":"text","speaker":"나레이션","english":"","japanese":"しっかりと二人に吸い付かれた内側で、ペニスの先端は蠢く舌によって絡め取られていく。","korean":"두 사람의 입술이 단단히 붙은 안에서 꿈틀거리는 혀들이 성기 끝을 감았다.","recordingScript":"","memo":"음성 29","voice":"","phaseId":"end01h-P1"},
{"rowNumber":32,"id":"end01h.mes#8329","kind":"text","speaker":"시에","english":"","japanese":"紫衣「れろっ、ちゅばっ！　……じゅるっ……あむっ……んふぅ……」","korean":"핥짝, 쪽! ……후룩…… 앙…… 후우……","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":33,"id":"end01h.mes#8593","kind":"text","speaker":"안리","english":"","japanese":"杏里「ぴちゃ、ぴちゃっ……れろれろっ……ちゅううっ……ちゅばっ！　ちゅっ、ちゅっ！」","korean":"찰박, 찰박…… 핥짝, 핥짝…… 쮸우우…… 쪽! 쪽, 쪽!","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":34,"id":"end01h.mes#8759","kind":"text","speaker":"나레이션","english":"","japanese":"リズムの違う二人の舌に絶え間なく嬲られ、その刺激で腰はガクガクと震えつつも俺は必死に熱い迸りを押さえ、射精を先延ばしにしていく。","korean":"서로 다른 박자로 움직이는 두 혀가 쉴 새 없이 자극했다. 허리가 덜덜 떨렸지만, 뜨겁게 치밀어 오르는 감각을 필사적으로 참으며 사정을 늦췄다.","recordingScript":"","memo":"음성 32","voice":"","phaseId":"end01h-P1"},
{"rowNumber":35,"id":"end01h.mes#8969","kind":"text","speaker":"토모키","english":"","japanese":"大樹「つ、次は交互に……」","korean":"다, 다음엔 번갈아서……","recordingScript":"","memo":"음성 33","voice":"","phaseId":"end01h-P1"},
{"rowNumber":36,"id":"end01h.mes#9214","kind":"text","speaker":"나레이션","english":"","japanese":"搾り出すように要望を伝えると、すっと顔を引いた杏里の動きに合わせ、紫衣が顔を突き出し肉棒を深く咥えこむ。","korean":"가까스로 부탁을 꺼내자 안리가 얼굴을 살짝 물렸다. 그와 동시에 시에가 얼굴을 내밀어 성기를 깊게 물었다.","recordingScript":"","memo":"음성 34","voice":"","phaseId":"end01h-P1"},
{"rowNumber":37,"id":"end01h.mes#9518","kind":"text","speaker":"시에","english":"","japanese":"紫衣「んんっ……じゅるっ……ちゅうっ……」","korean":"으응…… 후룩…… 쮸우……","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":38,"id":"end01h.mes#9642","kind":"text","speaker":"나레이션","english":"","japanese":"紫衣はペニスを飲み込むと、ねっとりと舌を亀頭に絡みつかせる。","korean":"시에는 성기를 깊이 삼키고 혀를 귀두에 끈적하게 감았다.","recordingScript":"","memo":"음성 36","voice":"","phaseId":"end01h-P1"},
{"rowNumber":39,"id":"end01h.mes#9784","kind":"text","speaker":"나레이션","english":"","japanese":"そしてそのままたわわな乳房を揺らしながら、顔を激しく動かす派手な奉仕で肉棒を刺激していく。","korean":"풍만한 가슴을 흔들며 고개를 빠르게 움직여, 요란한 입놀림으로 성기를 자극했다.","recordingScript":"","memo":"음성 37","voice":"","phaseId":"end01h-P1"},
{"rowNumber":40,"id":"end01h.mes#10074","kind":"text","speaker":"시에","english":"","japanese":"紫衣「んっ、んっ！　んっ、んふぅ！」","korean":"으응, 으응! 으응, 후우!","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":41,"id":"end01h.mes#10310","kind":"text","speaker":"시에","english":"","japanese":"紫衣「じゅぶっ……じゅばっ！　……んふぅ！　んっ、んっ！　んんっ！」","korean":"쪽…… 쪽! ……후우! 으응, 으응! 으응!","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":42,"id":"end01h.mes#10460","kind":"text","speaker":"나레이션","english":"","japanese":"すぼめた口内とペニスの隙間に唾液まみれの舌を這わせ、喉奥に引き込んではバキュームで全体を強く吸い込んでいく。","korean":"오므린 입과 성기 사이로 침에 젖은 혀를 움직이고, 목 깊숙이 끌어들여 전체를 힘껏 빨았다.","recordingScript":"","memo":"음성 40","voice":"","phaseId":"end01h-P1"},
{"rowNumber":43,"id":"end01h.mes#10768","kind":"text","speaker":"시에","english":"","japanese":"紫衣「じゅるるっ！　じゅばっ！　じゅるるぅ！」","korean":"후루룩! 쪽! 후루룩!","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":44,"id":"end01h.mes#11014","kind":"text","speaker":"시에","english":"","japanese":"紫衣「んんっ……杏里……」","korean":"으응…… 안리……","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":45,"id":"end01h.mes#11377","kind":"text","speaker":"안리","english":"","japanese":"杏里「んっ……」","korean":"으응……","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":46,"id":"end01h.mes#11475","kind":"text","speaker":"나레이션","english":"","japanese":"激しい口淫にヒクついていた肉棒は、口内から出される事無くそのまま杏里の口へとバトンを手渡すようにフェラチオが交代される。","korean":"거센 입놀림에 움찔하던 성기는 입 밖으로 나오지도 않고, 바통을 건네듯 그대로 안리의 입으로 넘어갔다.","recordingScript":"","memo":"음성 44","voice":"","phaseId":"end01h-P1"},
{"rowNumber":47,"id":"end01h.mes#11932","kind":"text","speaker":"안리","english":"","japanese":"杏里「はむっ……んちゅぅ……」","korean":"앙…… 쮸우……","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":48,"id":"end01h.mes#12044","kind":"text","speaker":"나레이션","english":"","japanese":"杏里は亀頭だけをすっぽりと口内に納めると、きつい吸引で肉棒の先端に熱を吸い集めていく。","korean":"안리는 귀두만 쏙 머금고 힘껏 빨아 성기 끝으로 열기를 끌어모았다.","recordingScript":"","memo":"음성 46","voice":"","phaseId":"end01h-P1"},
{"rowNumber":49,"id":"end01h.mes#12330","kind":"text","speaker":"안리","english":"","japanese":"杏里「ちゅうぅ……んふぅ……れろっ……」","korean":"쮸우우…… 후우…… 핥짝……","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":50,"id":"end01h.mes#12452","kind":"text","speaker":"나레이션","english":"","japanese":"吸い付かれ充血が増す事で敏感となった裏筋に舌を当てると……","korean":"빨린 탓에 피가 몰려 예민해진 귀두 아래쪽에 혀를 댔다……","recordingScript":"","memo":"음성 48","voice":"","phaseId":"end01h-P1"},
{"rowNumber":51,"id":"end01h.mes#12592","kind":"text","speaker":"나레이션","english":"","japanese":"派手な紫衣の愛撫と違い、杏里は小さな動きでペニスの感じる場所を重点的に責め立て始めた。","korean":"화려한 시에의 손길과 달리 안리는 작게 움직이면서 가장 민감한 곳만 집중적으로 자극했다.","recordingScript":"","memo":"음성 49","voice":"","phaseId":"end01h-P1"},
{"rowNumber":52,"id":"end01h.mes#12878","kind":"text","speaker":"안리","english":"","japanese":"杏里「くちゅっ、くちゅっ、ちゅばっ！　……れろれろっ……じゅるっ！」","korean":"쪽, 쪽, 쪽! ……핥짝, 핥짝…… 후룩!","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":53,"id":"end01h.mes#13146","kind":"text","speaker":"안리","english":"","japanese":"杏里「れろっ、んちゅっ、んくっ、んんっ！　……ちゅうぅぅ！」","korean":"핥짝, 쪽, 으윽, 으응! ……쮸우우!","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":54,"id":"end01h.mes#13288","kind":"text","speaker":"나레이션","english":"","japanese":"尿道の奥の奥まで吸い出すような杏里の攻撃的な奉仕。","korean":"요도 깊은 곳까지 빨아낼 것처럼 안리의 입놀림은 집요했다.","recordingScript":"","memo":"음성 52","voice":"","phaseId":"end01h-P1"},
{"rowNumber":55,"id":"end01h.mes#13420","kind":"text","speaker":"나레이션","english":"","japanese":"そのとろけるような刺激に俺の意思は溶かされ……急速に湧き上がる絶頂のシグナルが、脳裏に鳴り響いていく。","korean":"녹아내릴 듯한 자극에 참으려던 마음이 풀렸다…… 절정이 순식간에 차올랐다.","recordingScript":"","memo":"음성 53","voice":"","phaseId":"end01h-P1"},
{"rowNumber":56,"id":"end01h.mes#13604","kind":"text","speaker":"토모키","english":"","japanese":"大樹「くうっ！　ああっ、で、出る！　……っ！？　ふ、二人でっ！　早くぅ！」","korean":"으으! 아앗, 나, 나온다! ……!? 두, 둘이서! 빨리!","recordingScript":"","memo":"음성 54","voice":"","phaseId":"end01h-P1"},
{"rowNumber":57,"id":"end01h.mes#14015","kind":"text","speaker":"시에 & 안리","english":"","japanese":"紫衣＆杏里「んんっ、んんんんっ！！！」","korean":"으응, 으으으응!!!","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":58,"id":"end01h.mes#14135","kind":"text","speaker":"나레이션","english":"","japanese":"亀頭に強く吸い付く二人の唇から腰を引くと、噴き出すように二人の間へ熱く滾る精液を解き放った。","korean":"귀두를 세게 빨던 두 입술 사이에서 허리를 빼자, 뜨겁게 끓던 정액이 둘 사이로 뿜어져 나왔다.","recordingScript":"","memo":"음성 56","voice":"","phaseId":"end01h-P1"},
{"rowNumber":59,"id":"end01h.mes#14662","kind":"text","speaker":"시에","english":"","japanese":"紫衣「んぁ！　……出た出た……」","korean":"아아! ……나왔어, 나왔어……","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":60,"id":"end01h.mes#15129","kind":"text","speaker":"안리","english":"","japanese":"杏里「はぁぁ……沢山……元気よく出てきますね」","korean":"하아아…… 많네요…… 기세 좋게 나와요.","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":61,"id":"end01h.mes#15492","kind":"text","speaker":"나레이션","english":"","japanese":"浴びせかけられる白濁に二人は口から舌を出しながら、その身の全てでほとばしる熱い粘液を受けとめていく……","korean":"두 사람은 혀를 쭉 내민 채 세차게 뿜어지는 뜨거운 정액을 온몸으로 받아 냈다……","recordingScript":"","memo":"음성 59","voice":"","phaseId":"end01h-P1"},
{"rowNumber":62,"id":"end01h.mes#15934","kind":"text","speaker":"시에","english":"","japanese":"紫衣「あむっ……んんっ……」","korean":"앙…… 으응……","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":63,"id":"end01h.mes#16044","kind":"text","speaker":"나레이션","english":"","japanese":"吐精への勢いがなくなりかけると、紫衣はパクリと亀頭を口へ含み、中に残る精液を吸い出し始めた。","korean":"사정이 잦아들자 시에는 귀두를 덥석 물고 안에 남은 정액까지 빨아내기 시작했다.","recordingScript":"","memo":"음성 61","voice":"","phaseId":"end01h-P1"},
{"rowNumber":64,"id":"end01h.mes#16336","kind":"text","speaker":"시에","english":"","japanese":"紫衣「んっ、んんっ……ちゅう、ちゅぱっ……れろっ……ちゅうぅ……」","korean":"으응, 으응…… 쮸우, 쪽…… 핥짝…… 쮸우우……","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":65,"id":"end01h.mes#16602","kind":"text","speaker":"시에","english":"","japanese":"紫衣「んふぅ……くちゅっ、ちゅばっ、ちゅっ……れろれろ……ちゅうぅ……」","korean":"후우…… 쪽, 쪽, 쪽…… 핥짝, 핥짝…… 쮸우우……","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":66,"id":"end01h.mes#16756","kind":"text","speaker":"나레이션","english":"","japanese":"お掃除フェラにしては過剰な刺激に、ビクつく肉棒から新たなカウパーが紫衣の滑る口内へ注ぎ込まれる。","korean":"마무리라고 하기엔 자극이 지나쳤다. 움찔대는 성기에서 새로 나온 쿠퍼액이 시에의 입으로 흘러들었다.","recordingScript":"","memo":"음성 64","voice":"","phaseId":"end01h-P1"},
{"rowNumber":67,"id":"end01h.mes#17052","kind":"text","speaker":"안리","english":"","japanese":"杏里「紫衣お姉様……私にもともくんの新鮮な精子を分けてください……」","korean":"시에 언니…… 저한테도 토모 군 정액 좀 나눠 주세요……","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":68,"id":"end01h.mes#17487","kind":"text","speaker":"시에","english":"","japanese":"紫衣「んあっ……いいわ……舌を出して……」","korean":"아앗…… 좋아…… 혀 내밀어……","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":69,"id":"end01h.mes#17729","kind":"text","speaker":"안리","english":"","japanese":"杏里「はい……ありがとうございます……れろっ、れろっ……んっ」","korean":"네…… 고마워요…… 핥짝, 핥짝…… 으응.","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":70,"id":"end01h.mes#18128","kind":"text","speaker":"안리","english":"","japanese":"杏里「ちゅぅ……れろぅ……んふぅ……ちゅうぅ……ちゅばっ……ちゅっ」","korean":"쮸우…… 핥짝…… 후우…… 쮸우우…… 쪽…… 쪽.","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":71,"id":"end01h.mes#18278","kind":"text","speaker":"나레이션","english":"","japanese":"二人はお互いの匂いを嗅ぎ合うように、鼻先を重ね唇を強く擦りつけ合う。","korean":"두 사람은 서로의 냄새를 맡으려는 듯 코끝을 대고 입술을 꼭 문질렀다.","recordingScript":"","memo":"음성 69","voice":"","phaseId":"end01h-P1"},
{"rowNumber":72,"id":"end01h.mes#18546","kind":"text","speaker":"시에","english":"","japanese":"紫衣「んんっ、ちゅっ……ちゅばっ……んふぅ……」","korean":"으응, 쪽…… 쪽…… 후우……","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":73,"id":"end01h.mes#18676","kind":"text","speaker":"나레이션","english":"","japanese":"弄るように蠢く唇の隙間から、二人はお互いの口内へ舌を差し入れていく……","korean":"입술을 맞물린 채 그 틈으로 서로의 입에 혀를 밀어 넣었다……","recordingScript":"","memo":"음성 71","voice":"","phaseId":"end01h-P1"},
{"rowNumber":74,"id":"end01h.mes#18828","kind":"text","speaker":"나레이션","english":"","japanese":"そして雛鳥に餌を分け与えるように舌を絡め合い、精液と唾液を共有する熱の篭ったキスを重ね始めた。","korean":"새끼 새에게 먹이를 나눠 주듯 혀를 얽으며 정액과 침을 나누는 뜨거운 입맞춤을 이어 갔다.","recordingScript":"","memo":"음성 72","voice":"","phaseId":"end01h-P1"},
{"rowNumber":75,"id":"end01h.mes#19122","kind":"text","speaker":"안리","english":"","japanese":"杏里「んっ、んくっ……れろっ……ちゅっ……ちゅばっ……んふぅ」","korean":"으응, 으윽…… 핥짝…… 쪽…… 쪽…… 후우.","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":76,"id":"end01h.mes#19384","kind":"text","speaker":"시에","english":"","japanese":"紫衣「くちゅっ、ちゅぅ……んんっ……れろっ……ちゅうっ……」","korean":"쪽, 쮸우…… 으응…… 핥짝…… 쮸우……","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":77,"id":"end01h.mes#19666","kind":"text","speaker":"나레이션","english":"","japanese":"顔と顔の距離が微かに広がると、二人は触れ合わせた舌を器用に動かし、その上に乗る白濁を弄ぶように舐め合い続けていく。","korean":"얼굴 사이가 살짝 벌어지자 두 사람은 맞닿은 혀를 능숙하게 움직여 그 위에 묻은 정액을 가지고 놀듯 핥았다.","recordingScript":"","memo":"음성 75","voice":"","phaseId":"end01h-P1"},
{"rowNumber":78,"id":"end01h.mes#19980","kind":"text","speaker":"안리","english":"","japanese":"杏里「れろっ、れろっ……はあぁ……んあっ……れろっ……んふぅん……」","korean":"핥짝, 핥짝…… 하아…… 아앗…… 핥짝…… 흐응……","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":79,"id":"end01h.mes#20248","kind":"text","speaker":"시에","english":"","japanese":"紫衣「ぴちゃっ、れろっ……はあっ……れろっ……れろっ……んはあぁ……」","korean":"찰박, 핥짝…… 하앗…… 핥짝…… 핥짝…… 하아아……","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":80,"id":"end01h.mes#20658","kind":"text","speaker":"안리","english":"","japanese":"杏里「んんっ……んちゅぅ、ちゅばっ、れろっ……ちゅぱちゅぱっ……んちゅっ、んちゅぅう……」","korean":"으응…… 쮸우, 쪽, 핥짝…… 쪽쪽…… 쪽, 쮸우우……","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":81,"id":"end01h.mes#20948","kind":"text","speaker":"시에","english":"","japanese":"紫衣「んふぅ！　んんっ、ちゅるっ……ちゅぱっ、んんっ、ちゅ、ちゅぷっ、ちゅびっ、んんっ、んふぅ……」","korean":"후우! 으응, 쪽…… 쪽, 으응, 쪽, 쪽, 쪼옥, 으응, 후우……","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":82,"id":"end01h.mes#21130","kind":"text","speaker":"나레이션","english":"","japanese":"淫らに互いの舌を貪り合う紫衣と杏里は、次第にお互いの身体の熱気を高め……","korean":"서로의 혀를 야릇하게 탐하는 시에와 안리의 몸은 점점 더 뜨거워졌고……","recordingScript":"","memo":"음성 80","voice":"","phaseId":"end01h-P1"},
{"rowNumber":83,"id":"end01h.mes#21284","kind":"text","speaker":"나레이션","english":"","japanese":"二人から湧き上がる雌の匂いで、俺の興奮もより強く煽られていく……","korean":"둘에게서 풍겨 오는 체취에 내 흥분도 더 거세졌다……","recordingScript":"","memo":"음성 81","voice":"","phaseId":"end01h-P1"},
{"rowNumber":84,"id":"end01h.mes#21430","kind":"text","speaker":"나레이션","english":"","japanese":"高ぶる興奮に揺れ始めた腰の動きを見て、俺は涎をたらす様に亀頭から先走りをツーッとシーツに零れ落とした。","korean":"흥분이 차오르며 흔들리기 시작한 두 허리를 보니, 귀두에서 쿠퍼액이 침처럼 흘러 시트에 떨어졌다.","recordingScript":"","memo":"음성 82","voice":"","phaseId":"end01h-P1"},
{"rowNumber":85,"id":"end01h.mes#21872","kind":"text","speaker":"안리","english":"","japanese":"杏里「はあぁ……紫衣お姉様の舌……熱くてすべすべして……舐めてるだけで気持ちいい……んあぁ……れろ……んはぁ……」","korean":"하아…… 시에 언니 혀…… 뜨겁고 매끈해서…… 핥기만 해도 기분 좋아요…… 아아…… 핥짝…… 하아……","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":86,"id":"end01h.mes#22186","kind":"text","speaker":"시에","english":"","japanese":"紫衣「んんっ……貴方の舌だって、とても魅力的よ……唾液も甘くて美味しいし……ずっと舐めていたいわ……んん……れろっ……」","korean":"으응…… 네 혀도 아주 매력적이야…… 침도 달고 맛있어서…… 계속 핥고 싶어…… 으응…… 핥짝……","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":87,"id":"end01h.mes#22388","kind":"text","speaker":"토모키","english":"","japanese":"大樹「……そろそろ、俺も混ぜてくれないか？」","korean":"……슬슬 나도 끼워 줄래?","recordingScript":"","memo":"음성 85","voice":"","phaseId":"end01h-P1"},
{"rowNumber":88,"id":"end01h.mes#22772","kind":"text","speaker":"안리","english":"","japanese":"杏里「れろっ……あ……少しだけ忘れてました」","korean":"핥짝…… 아…… 잠깐 잊고 있었어요.","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":89,"id":"end01h.mes#23153","kind":"text","speaker":"시에","english":"","japanese":"紫衣「……そうだったわ……貴方も居たのよね」","korean":"……참, 그랬지…… 너도 있었네.","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":90,"id":"end01h.mes#23279","kind":"text","speaker":"토모키","english":"","japanese":"大樹「……し、紫衣はいいとして……杏里に言われると、もしかして本当にそう思われてたのかもって……思っちまうだろうが……」","korean":"……시, 시에는 그렇다 쳐도…… 안리가 그렇게 말하면 진짜로 날 잊은 줄 알잖아……","recordingScript":"","memo":"음성 88","voice":"","phaseId":"end01h-P1"},
{"rowNumber":91,"id":"end01h.mes#23599","kind":"text","speaker":"안리","english":"","japanese":"杏里「ともくん、もちろん冗談ですよ」","korean":"토모 군, 당연히 농담이에요.","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":92,"id":"end01h.mes#23835","kind":"text","speaker":"시에","english":"","japanese":"紫衣「そうよ……だからそんな情けない顔しないで……」","korean":"그래…… 그러니까 그렇게 풀이 죽은 얼굴 하지 마……","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":93,"id":"end01h.mes#24087","kind":"text","speaker":"안리","english":"","japanese":"杏里「はい……ですから、その大きく膨らんだオチンチンを……」","korean":"네…… 그러니까 그 커다랗게 부푼 자지를……","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":94,"id":"end01h.mes#24347","kind":"text","speaker":"안리","english":"","japanese":"杏里「今度は私達の、発情してるおまんこへ入れてください……」","korean":"이번에는 달아오른 저희 보지에 넣어 주세요……","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":95,"id":"end01h.mes#24489","kind":"text","speaker":"토모키","english":"","japanese":"大樹「……ああ、まかせておけ！」","korean":"……그래, 맡겨 둬!","recordingScript":"","memo":"음성 93","voice":"","phaseId":"end01h-P1"},
{"rowNumber":96,"id":"end01h.mes#25917","kind":"text","speaker":"나레이션","english":"","japanese":"縦に並ぶ二つの濡れそぼる花弁は、艶やかな色香を放っている。","korean":"위아래로 나란히 놓인 흠뻑 젖은 두 음부가 요염해 보였다.","recordingScript":"","memo":"음성 95","voice":"","phaseId":"end01h-P1"},
{"rowNumber":97,"id":"end01h.mes#26057","kind":"text","speaker":"나레이션","english":"","japanese":"そして自分達が愛撫した肉棒を受け入れるため、二人ともぱっくりと開いた膣口をヒクヒクと蠢かせていた。","korean":"스스로 자극한 성기를 받아들이려는 듯 두 사람 다 활짝 벌어진 질 입구를 움찔거렸다.","recordingScript":"","memo":"음성 96","voice":"","phaseId":"end01h-P1"},
{"rowNumber":98,"id":"end01h.mes#26237","kind":"text","speaker":"나레이션","english":"","japanese":"贅沢なご馳走を前に獣の如く襲いたい衝動を押さえ込み……俺は上下どちらの膣へ１本しかない肉棒を突っ込むべきか、思案していく。","korean":"눈앞의 호사에 짐승처럼 달려들고 싶은 충동을 참았다. 하나뿐인 성기를 위아래 중 어디에 넣을지 고민했다.","recordingScript":"","memo":"음성 97","voice":"","phaseId":"end01h-P1"},
{"rowNumber":99,"id":"end01h.mes#26559","kind":"text","speaker":"시에","english":"","japanese":"紫衣「ねぇ、大樹……どちらへ先に入れるの？」","korean":"있잖아, 토모키…… 어디에 먼저 넣을 거야?","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":100,"id":"end01h.mes#26685","kind":"text","speaker":"토모키","english":"","japanese":"大樹「そうだな……飢えた犬みたいにビラビラをパックり開いて涎を垂れ流す……はしたない紫衣のおまんこからかな」","korean":"글쎄…… 배고픈 개처럼 음순을 활짝 벌리고 침을 줄줄 흘리는…… 낯 뜨거운 시에 보지부터 할까.","recordingScript":"","memo":"음성 99","voice":"","phaseId":"end01h-P1"},
{"rowNumber":101,"id":"end01h.mes#27130","kind":"text","speaker":"시에","english":"","japanese":"紫衣「……は、はしたないって……べ、別にそこまで飢えてないわよ！」","korean":"……나, 낯 뜨겁다니…… 그, 그렇게까지 간절한 건 아니야!","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":102,"id":"end01h.mes#27396","kind":"text","speaker":"시에","english":"","japanese":"紫衣「……そ、それに杏里が小ぶりすぎるだけで、私のサイズが普通……」","korean":"……그, 그리고 안리가 너무 작은 거지, 내가 보통이야……","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":103,"id":"end01h.mes#27546","kind":"text","speaker":"토모키","english":"","japanese":"大樹「はいはい……」","korean":"그래, 그래……","recordingScript":"","memo":"음성 102","voice":"","phaseId":"end01h-P1"},
{"rowNumber":104,"id":"end01h.mes#27648","kind":"text","speaker":"나레이션","english":"","japanese":"ツンツンとした物言いとは裏腹に、選ばれた事の喜びでモジモジと揺れる紫衣の下半身に腰を寄せていく。","korean":"쌀쌀맞은 말투와 달리 골라 준 게 기쁜지 시에가 하반신을 꼼지락거렸다. 그쪽으로 허리를 바짝 가져갔다.","recordingScript":"","memo":"음성 103","voice":"","phaseId":"end01h-P1"},
{"rowNumber":105,"id":"end01h.mes#27826","kind":"text","speaker":"나레이션","english":"","japanese":"そしてそのまま、俺は熱く滑る膣口へ亀頭をずぶりと差し込んでいった。","korean":"그리고 뜨겁고 미끄러운 질 입구에 귀두를 밀어 넣었다.","recordingScript":"","memo":"음성 104","voice":"","phaseId":"end01h-P1"},
{"rowNumber":106,"id":"end01h.mes#28232","kind":"text","speaker":"시에","english":"","japanese":"紫衣「んああぁぁ！」","korean":"아아아아!","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":107,"id":"end01h.mes#28421","kind":"text","speaker":"나레이션","english":"","japanese":"発情した紫衣は蜜壷のヒダで熱烈にペニスを包み、カリで壁を擦られるたび腰をビクビクと震わせ獣のような嬌声を張り上げる。","korean":"달아오른 시에는 질 주름으로 성기를 꼭 감쌌다. 귀두가 질벽을 스칠 때마다 허리를 움찔거리며 짐승처럼 신음했다.","recordingScript":"","memo":"음성 106","voice":"","phaseId":"end01h-P1"},
{"rowNumber":108,"id":"end01h.mes#28737","kind":"text","speaker":"시에","english":"","japanese":"紫衣「んおおおぉぉぉ！　……はあっ！　ふうっん！　んはあっ！」","korean":"으어어어! ……하앗! 후응! 하아앗!","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":109,"id":"end01h.mes#28999","kind":"text","speaker":"시에","english":"","japanese":"紫衣「ああっ！　ふうっ！　はうっ！　あっ！　はぁん！」","korean":"아앗! 후우! 하으! 앗! 하앙!","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":110,"id":"end01h.mes#29173","kind":"text","speaker":"토모키","english":"","japanese":"大樹「……イヤなら抜いて杏里を先にしようか？」","korean":"……싫으면 빼고 안리부터 할까?","recordingScript":"","memo":"음성 109","voice":"","phaseId":"end01h-P1"},
{"rowNumber":111,"id":"end01h.mes#29419","kind":"text","speaker":"시에","english":"","japanese":"紫衣「っ！？　い、イヤよ！　……んぐっ……い、入れたのなら……当然、最後まで……」","korean":"……!? 시, 싫어! ……으윽…… 너, 넣었으면…… 당연히 끝까지……","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":112,"id":"end01h.mes#29841","kind":"text","speaker":"시에","english":"","japanese":"紫衣「……んぐっ……こ、このまま中で射精せずに抜いたりしたら……承知しないわよ……」","korean":"……으윽…… 이, 이대로 안에 싸지도 않고 빼면…… 가만 안 둬……","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":113,"id":"end01h.mes#30007","kind":"text","speaker":"토모키","english":"","japanese":"大樹「仰せのままに……」","korean":"분부대로……","recordingScript":"","memo":"음성 112","voice":"","phaseId":"end01h-P1"},
{"rowNumber":114,"id":"end01h.mes#30113","kind":"text","speaker":"나레이션","english":"","japanese":"俺は彼女の願いを叶える為、腰をがっしりと掴むと、さらなる快感を与えようと腰を大きく振りたてていく。","korean":"바라는 대로 해 주려고 시에의 허리를 꼭 붙잡고, 더 큰 쾌감을 주려고 허리를 크게 움직였다.","recordingScript":"","memo":"음성 113","voice":"","phaseId":"end01h-P1"},
{"rowNumber":115,"id":"end01h.mes#30638","kind":"text","speaker":"시에","english":"","japanese":"紫衣「はあっ！　ふうっ！　んあっ、あっ！　ああっ！」","korean":"하앗! 후우! 아앗, 앗! 아앗!","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":116,"id":"end01h.mes#30890","kind":"text","speaker":"시에","english":"","japanese":"紫衣「あっ！　あぁ！　……ふうっ！　ふぅん！　はあっ！　んはぁ！」","korean":"앗! 아아! ……후우! 흐응! 하앗! 하아!","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":117,"id":"end01h.mes#31156","kind":"text","speaker":"안리","english":"","japanese":"杏里「……ふふ……紫衣お姉様、気持ちよさそう……」","korean":"……후후…… 시에 언니, 기분 좋아 보여요……","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":118,"id":"end01h.mes#31406","kind":"text","speaker":"시에","english":"","japanese":"紫衣「はあぁ！　いいっ！　いいのぉ！　いいわぁ！」","korean":"하아! 좋아! 좋아아! 정말 좋아!","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":119,"id":"end01h.mes#31656","kind":"text","speaker":"시에","english":"","japanese":"紫衣「ふうぅ！　大樹の硬いペニスがぁ！　……んんっ！　……し、子宮に響くぅ……熱いのが込み上げるっ！」","korean":"후우! 토모키의 단단한 자지가! ……으응! ……자, 자궁까지 울려어…… 뜨거운 게 차올라!","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":120,"id":"end01h.mes#31958","kind":"text","speaker":"안리","english":"","japanese":"杏里「……はあぁ……私も、早く感じたい……」","korean":"……하아…… 저도 빨리 느끼고 싶어요……","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":121,"id":"end01h.mes#32202","kind":"text","speaker":"시에","english":"","japanese":"紫衣「んあっ！　ま、まだ駄目っ！　で、でも……貴方にも少し分けてあげる……ちゅぶっ！」","korean":"아앗! 아, 아직 안 돼! 그, 그래도…… 너한테도 조금 나눠 줄게…… 쪽!","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":122,"id":"end01h.mes#32628","kind":"text","speaker":"시에","english":"","japanese":"紫衣「ちゅばっ！　ちゅうっ！　んはあぁ……んちゅっ、れろっ、ちゅぶっ……んふぅ！」","korean":"쪽! 쮸우! 하아아…… 쪽, 핥짝, 쪽…… 후우!","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":123,"id":"end01h.mes#32792","kind":"text","speaker":"나레이션","english":"","japanese":"湧き上がる快感を、口付けで伝えていく紫衣……","korean":"치밀어 오른 쾌감을 시에는 입맞춤으로 전했다……","recordingScript":"","memo":"음성 122","voice":"","phaseId":"end01h-P1"},
{"rowNumber":124,"id":"end01h.mes#33036","kind":"text","speaker":"안리","english":"","japanese":"杏里「……はむっ、れろっ……れろれろっ……んちゅぶっ！　ちゅばっ！　ちゅううっ！」","korean":"……앙, 핥짝…… 핥짝, 핥짝…… 쪽! 쪽! 쮸우우!","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":125,"id":"end01h.mes#33200","kind":"text","speaker":"나레이션","english":"","japanese":"だが、次第に杏里の舌に責め負け……口内から生まれた快感に、膣壁をギュウギュウと収縮させていく。","korean":"그러다 안리의 혀에 서서히 밀려났다. 입안에서 시작된 쾌감에 질벽이 꽉꽉 조였다.","recordingScript":"","memo":"음성 124","voice":"","phaseId":"end01h-P1"},
{"rowNumber":126,"id":"end01h.mes#33494","kind":"text","speaker":"시에","english":"","japanese":"紫衣「んふぅ！　ふぅん！　……んっ！　んんっ！　んんんっ！　んふうぅんっ！」","korean":"후우! 흐응! ……으응! 으응! 으으응! 흐으응!","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":127,"id":"end01h.mes#33770","kind":"text","speaker":"안리","english":"","japanese":"杏里「ちゅばっ！　っんちゅぅ！　じゅばっ！　ちゅうぅぅ……んふぅ！　れろっ、ちゅぷっ、ちゅうっ！」","korean":"쪽! 쮸우! 쪽! 쮸우우…… 후우! 핥짝, 쪽, 쮸우!","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":128,"id":"end01h.mes#33950","kind":"text","speaker":"나레이션","english":"","japanese":"蜜壷と口内を同時に責めたてられた紫衣は、小さな絶頂の波を幾度も浴び……その度に下腹部や太股をプルプルと震わせていく。","korean":"아래와 입이 동시에 자극을 받자 시에는 작은 절정을 몇 번이나 느꼈다. 그때마다 아랫배와 허벅지가 파르르 떨렸다.","recordingScript":"","memo":"음성 127","voice":"","phaseId":"end01h-P1"},
{"rowNumber":129,"id":"end01h.mes#34266","kind":"text","speaker":"시에","english":"","japanese":"紫衣「んふううぅ！！　ふうっ！　んっ！　んふぅう！　ふうっ！　ふううっ！　ふうううぅ！！」","korean":"후우우우!! 후우! 으응! 후우우! 후우! 후우우! 후우우우!!","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":130,"id":"end01h.mes#34438","kind":"text","speaker":"나레이션","english":"","japanese":"二人に責め続けられ、紫衣の震えの間隔が狭まり……大きな絶頂の予兆が現れる。","korean":"둘이 계속 몰아붙이자 시에의 몸이 점점 더 자주 떨렸다. 큰 절정이 다가오는 기색이었다.","recordingScript":"","memo":"음성 129","voice":"","phaseId":"end01h-P1"},
{"rowNumber":131,"id":"end01h.mes#34594","kind":"text","speaker":"나레이션","english":"","japanese":"そこで俺は主導権を主張するように、紫衣の子宮口へ熱く膨らんだ亀頭をグイグイとめり込ませるように押し込んでいく。","korean":"주도권을 되찾듯 뜨겁게 부푼 귀두를 시에의 자궁 입구에 거듭 깊이 눌렀다.","recordingScript":"","memo":"음성 130","voice":"","phaseId":"end01h-P1"},
{"rowNumber":132,"id":"end01h.mes#35044","kind":"text","speaker":"시에","english":"","japanese":"紫衣「ぷはあぁ！　ひいぃ！　だ、駄目っ！　はひぃ！？　あっ、ああっ！！」","korean":"푸하아! 히익! 아, 안 돼! 히익!? 앗, 아앗!!","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":133,"id":"end01h.mes#35316","kind":"text","speaker":"시에","english":"","japanese":"紫衣「はうううっ……入るぅ……ペニスが奥にぃ……子宮にくるぅ！　はあっ！　んあぁあっ！」","korean":"하으으…… 들어와아…… 자지가 깊숙이…… 자궁까지 와아! 하앗! 아아앗!","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":134,"id":"end01h.mes#35486","kind":"text","speaker":"나레이션","english":"","japanese":"悲鳴にも似た激しい嬌声を上げる紫衣を虐めるようにパンパンと腰を打ち付ける。","korean":"비명처럼 높게 신음하는 시에를 괴롭히듯 허리를 탁탁 부딪쳤다.","recordingScript":"","memo":"음성 133","voice":"","phaseId":"end01h-P1"},
{"rowNumber":135,"id":"end01h.mes#35642","kind":"text","speaker":"나레이션","english":"","japanese":"すると紫衣は涙を流しつつ、内側から膨らむ快感の熱に全身を捩じらせていく。","korean":"시에는 눈물을 흘리며, 안에서 커지는 쾌감에 온몸을 뒤틀었다.","recordingScript":"","memo":"음성 134","voice":"","phaseId":"end01h-P1"},
{"rowNumber":136,"id":"end01h.mes#35914","kind":"text","speaker":"시에","english":"","japanese":"紫衣「気持ちよすぎて……ああっ、あ、頭が真っ白にぃ！　……んはぁ！　いいっ、いいっ！　駄目っ、駄目ぇ……んああぁぁ！」","korean":"너무 좋아서…… 아앗, 머, 머리가 하얘져어! ……하아! 좋아, 좋아! 안 돼, 안 돼에…… 아아아아!","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":137,"id":"end01h.mes#36232","kind":"text","speaker":"시에","english":"","japanese":"紫衣「はぁ、はあぁ！　もう身体に力が入らない！　ああっ、うううっ！　んはぁあ！」","korean":"하아, 하아! 이제 몸에 힘이 안 들어가! 아앗, 으으윽! 하아아!","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":138,"id":"end01h.mes#36394","kind":"text","speaker":"나레이션","english":"","japanese":"膣を硬い肉棒で擦られる快感によがる紫衣……","korean":"단단한 성기에 질 안이 쓸리는 쾌감에 시에가 몸부림쳤다……","recordingScript":"","memo":"음성 137","voice":"","phaseId":"end01h-P1"},
{"rowNumber":139,"id":"end01h.mes#36518","kind":"text","speaker":"나레이션","english":"","japanese":"彼女へ追い討ちをかけるように、杏里はグニグニと豊満な乳房を揉みしだき始めた。","korean":"한층 더 몰아붙이듯 안리는 풍만한 가슴을 주무르기 시작했다.","recordingScript":"","memo":"음성 138","voice":"","phaseId":"end01h-P1"},
{"rowNumber":140,"id":"end01h.mes#36794","kind":"text","speaker":"시에","english":"","japanese":"紫衣「はあぁん！　お、おっぱいもなんてぇ！　ああっ、あはぁ！　む、無理ぃ！　杏里！　と止めてぇ！　……ふうぅ、はあああぁぁぅぅ！！」","korean":"하아앙! 가, 가슴까지! 아앗, 아하! 아, 안 돼에! 안리! 그, 그만해애! ……후우, 하아아아!!","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":141,"id":"end01h.mes#37126","kind":"text","speaker":"안리","english":"","japanese":"杏里「駄目です……山口さんに、弱い所を教えてもらいましたので試させてもらいますね」","korean":"안 돼요…… 야마구치 씨한테 약한 데를 들었으니 한번 해 볼게요.","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":142,"id":"end01h.mes#37290","kind":"text","speaker":"토모키","english":"","japanese":"大樹「ほうほう……その秘伝は是非俺にも教えて欲しい所だ……」","korean":"그렇군…… 그 비법은 나한테도 꼭 알려 줘……","recordingScript":"","memo":"음성 141","voice":"","phaseId":"end01h-P1"},
{"rowNumber":143,"id":"end01h.mes#37550","kind":"text","speaker":"시에","english":"","japanese":"紫衣「ま、茉莉子……あの子は、もぉ！　んあっ、あぁん！」","korean":"마, 마리코…… 걘 정말! 아앗, 아앙!","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":144,"id":"end01h.mes#37806","kind":"text","speaker":"안리","english":"","japanese":"杏里「紫衣お姉様は、基本乱暴に揉まれるのが好きなんですけど……こうして焦らすように全体をゆっくり揉まれるのも好きらしいです」","korean":"시에 언니는 원래 거칠게 주무르는 걸 좋아하지만…… 이렇게 애태우듯 천천히 전체를 주무르는 것도 좋대요.","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":145,"id":"end01h.mes#38130","kind":"text","speaker":"시에","english":"","japanese":"紫衣「す、好きだけど……あっ、あぁん……ペニスで突かれながらじゃないわよ！」","korean":"조, 좋긴 한데…… 앗, 아앙…… 자지로 찔리는 중에는 아니야!","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":146,"id":"end01h.mes#38406","kind":"text","speaker":"안리","english":"","japanese":"杏里「……そして、強弱をつけながら時間をかけて……たまに乳首もギュッと強く抓ってあげて……」","korean":"……그리고 힘을 줬다 뺐다 하며 오래 만지다가…… 가끔 유두도 꽉 집어 주고……","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":147,"id":"end01h.mes#38698","kind":"text","speaker":"시에","english":"","japanese":"紫衣「あひぃ！？　……あく、あぁん……胸がムズムズして……身体の力が抜ける……」","korean":"히익!? ……아윽, 아앙…… 가슴이 근질근질해서…… 몸에 힘이 풀려……","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":148,"id":"end01h.mes#38978","kind":"text","speaker":"시에","english":"","japanese":"紫衣「……いつもならしつこいぐらい揉まれないとならないのに……はあぁ、はぁん……杏里、貴方上手すぎよぉ……」","korean":"……평소에는 한참을 만져도 이렇지 않은데…… 하아, 하앙…… 안리, 너 너무 잘하잖아……","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":149,"id":"end01h.mes#39286","kind":"text","speaker":"안리","english":"","japanese":"杏里「ふふ……ありがとうございます、もっと感じさせてあげますね……」","korean":"후후…… 고마워요. 더 느끼게 해 줄게요……","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":150,"id":"end01h.mes#39554","kind":"text","speaker":"시에","english":"","japanese":"紫衣「はあっ！　あぁん！　……感じすぎて頭が真っ白に……こんなの無理ぃ……ば、馬鹿になるぅ！」","korean":"하앗! 아앙! ……너무 느껴져서 머리가 하얘져…… 이건 못 참아아…… 바, 바보가 될 것 같아아!","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":151,"id":"end01h.mes#39848","kind":"text","speaker":"안리","english":"","japanese":"杏里「紫衣お姉様なら大丈夫……このまま思いっきりイッてください」","korean":"시에 언니는 괜찮아요…… 이대로 마음껏 가요.","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":152,"id":"end01h.mes#39994","kind":"text","speaker":"토모키","english":"","japanese":"大樹「エロくていいぞ！　このまま全力でイカせてやる！」","korean":"야하고 좋은데! 이대로 힘껏 보내 줄게!","recordingScript":"","memo":"음성 151","voice":"","phaseId":"end01h-P1"},
{"rowNumber":153,"id":"end01h.mes#40248","kind":"text","speaker":"시에","english":"","japanese":"紫衣「あくっ！　ああっ！　ば、馬鹿！　……ああっ、あふぅう！　んあっ、ああっ、あぁん！」","korean":"아윽! 아앗! 바, 바보! ……아앗, 후우우! 아앗, 아앗, 아앙!","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":154,"id":"end01h.mes#40418","kind":"text","speaker":"나레이션","english":"","japanese":"杏里に押さえ込まれながら、激しい快感の嵐に紫衣は身体を悶えさせていく。","korean":"안리에게 붙들린 채 거센 쾌감에 시에의 몸이 뒤틀렸다.","recordingScript":"","memo":"음성 153","voice":"","phaseId":"end01h-P1"},
{"rowNumber":155,"id":"end01h.mes#40570","kind":"text","speaker":"나레이션","english":"","japanese":"そんな彼女の種付けを望み降り始めた子宮へ、俺ははちきれそうなほど熱く膨らんだ肉棒を叩きつける。","korean":"안에 싸 달라는 듯 내려온 자궁에, 터질 듯 뜨겁게 부푼 성기를 내리꽂았다.","recordingScript":"","memo":"음성 154","voice":"","phaseId":"end01h-P1"},
{"rowNumber":156,"id":"end01h.mes#40864","kind":"text","speaker":"시에","english":"","japanese":"紫衣「……ひいぃ！　凄っ、凄いのがっ！　来るっ、来ちゃうっ！　んああぁぁ！！」","korean":"……히익! 커, 큰 게! 온다, 와 버려! 아아아아!!","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":157,"id":"end01h.mes#41142","kind":"text","speaker":"시에","english":"","japanese":"紫衣「あはぁっ！　いいっ、イクっ！　イクわっ！　イクっ！　いぐ、いぐううう！！」","korean":"아하앗! 좋아, 가! 간다고! 가! 가, 가아아아!!","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":158,"id":"end01h.mes#41422","kind":"text","speaker":"시에","english":"","japanese":"紫衣「イクうううううぅぅぅぅぅぅううううう！！！」","korean":"가아아아아아아아아!!!","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":159,"id":"end01h.mes#41554","kind":"text","speaker":"나레이션","english":"","japanese":"絶頂にガクガクと震える紫衣の子宮へ、俺は込み上げた熱い子種を勢い良く注ぎ込んだ。","korean":"절정에 덜덜 떠는 시에의 자궁을 향해 치밀어 오른 뜨거운 정액을 힘껏 쏟았다.","recordingScript":"","memo":"음성 158","voice":"","phaseId":"end01h-P1"},
{"rowNumber":160,"id":"end01h.mes#42107","kind":"text","speaker":"시에","english":"","japanese":"紫衣「はあっ！　ああっ！　熱い、熱いぃ！　……大樹の精液が……どんどん中に注がれてぇ……」","korean":"하앗! 아앗! 뜨거워, 뜨겁다고오! ……토모키 정액이…… 자꾸 안으로 들어와서……","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":161,"id":"end01h.mes#42397","kind":"text","speaker":"시에","english":"","japanese":"紫衣「いいっ！　気持ちいいっ！　いっ、イクぅ……イッてるのに……そのままイクううぅぅ！！」","korean":"좋아! 기분 좋아! 가, 가아…… 이미 갔는데…… 또 가아아!!","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":162,"id":"end01h.mes#42687","kind":"text","speaker":"시에","english":"","japanese":"紫衣「んーーーーーーーーーーー！！！」","korean":"으으으으으으!!!","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":163,"id":"end01h.mes#42807","kind":"text","speaker":"나레이션","english":"","japanese":"ガクガクと震えていた紫衣の足の動きが収まっていくのに合わせ、徐々にペニスを締め付ける膣の締め付けが緩んでいく。","korean":"덜덜 떨리던 시에의 다리가 차츰 잠잠해지자 성기를 조이던 질도 조금씩 풀렸다.","recordingScript":"","memo":"음성 162","voice":"","phaseId":"end01h-P1"},
{"rowNumber":164,"id":"end01h.mes#43117","kind":"text","speaker":"시에","english":"","japanese":"紫衣「んはぁ！　はぁ、はぁ……ふぅ……んはぁ……はあぁ……」","korean":"하아! 하아, 하아…… 후우…… 하아…… 하아아……","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":165,"id":"end01h.mes#43404","kind":"text","speaker":"안리","english":"","japanese":"杏里「紫衣お姉様……暖かい」","korean":"시에 언니…… 따뜻해요.","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":166,"id":"end01h.mes#43514","kind":"text","speaker":"나레이션","english":"","japanese":"紫衣の顔を覗き見ると激しすぎる絶頂の中、これ以上無いほどに至福の顔をしたまま呆然としている。","korean":"시에의 얼굴을 들여다보니 격렬한 절정에 더없이 행복한 표정을 지은 채 멍해 있었다.","recordingScript":"","memo":"음성 165","voice":"","phaseId":"end01h-P1"},
{"rowNumber":167,"id":"end01h.mes#43688","kind":"text","speaker":"나레이션","english":"","japanese":"膣から抜き取った愛液塗れの肉竿で、杏里の白尻の谷間へ粘液をヌチョヌチョと擦り付けていく。","korean":"애액에 흠뻑 젖은 성기를 빼서 안리의 하얀 엉덩이 골에 끈적한 체액을 비볐다.","recordingScript":"","memo":"음성 166","voice":"","phaseId":"end01h-P1"},
{"rowNumber":168,"id":"end01h.mes#43858","kind":"text","speaker":"토모키","english":"","japanese":"大樹「ふぅ……んじゃ、次は杏里だな」","korean":"후우…… 그럼 다음은 안리네.","recordingScript":"","memo":"음성 167","voice":"","phaseId":"end01h-P1"},
{"rowNumber":169,"id":"end01h.mes#44231","kind":"text","speaker":"안리","english":"","japanese":"杏里「はい、ともくん」","korean":"네, 토모 군.","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":170,"id":"end01h.mes#44453","kind":"text","speaker":"안리","english":"","japanese":"杏里「紫衣お姉様の中に入っていた硬いおちんちんで……私の中をかき回してください」","korean":"시에 언니 안에 있던 단단한 자지로…… 제 안을 휘저어 주세요.","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":171,"id":"end01h.mes#44615","kind":"text","speaker":"나레이션","english":"","japanese":"肉欲まるだしの紫衣と違い、すまし顔で淫らな事を淡々と口走る杏里。","korean":"욕망을 숨김없이 드러낸 시에와 달리 안리는 태연한 얼굴로 야한 말을 담담하게 꺼냈다.","recordingScript":"","memo":"음성 170","voice":"","phaseId":"end01h-P1"},
{"rowNumber":172,"id":"end01h.mes#44761","kind":"text","speaker":"나레이션","english":"","japanese":"そのギャップのある煽りが、俺の興奮を激しくさそっていく。","korean":"그 얼굴과 말이 딴판이라 더 크게 흥분됐다.","recordingScript":"","memo":"음성 171","voice":"","phaseId":"end01h-P1"},
{"rowNumber":173,"id":"end01h.mes#44899","kind":"text","speaker":"나레이션","english":"","japanese":"尻穴が横に伸びるほど力強く臀部を押し広げると、俺は紫衣の性臭と温もりが残るペニスを小ぶりの花弁へと差し込んでいった。","korean":"항문이 옆으로 늘어날 만큼 양쪽 엉덩이를 힘껏 벌리고, 시에의 체취와 온기가 남은 성기를 안리의 작은 음순 사이로 밀어 넣었다.","recordingScript":"","memo":"음성 172","voice":"","phaseId":"end01h-P1"},
{"rowNumber":174,"id":"end01h.mes#45409","kind":"text","speaker":"안리","english":"","japanese":"杏里「んはあぁ……紫衣お姉様の中をかき回していたおちんちんが……入ってくる……」","korean":"하아아…… 시에 언니 안을 휘젓던 자지가…… 들어와요……","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":175,"id":"end01h.mes#45689","kind":"text","speaker":"안리","english":"","japanese":"杏里「あ、あくっ……んんっ、はあぁ……硬くて熱いおちんちん……んんっ……私のおまんこをいっぱいに広げていく……」","korean":"아, 아윽…… 으응, 하아…… 단단하고 뜨거운 자지가…… 으응…… 제 보지를 가득 벌려요……","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":176,"id":"end01h.mes#45883","kind":"text","speaker":"토모키","english":"","japanese":"大樹「くぅ……杏里のおまんこは……相変わらずキツキツだな……」","korean":"으으…… 안리 보지는…… 여전히 꽉 조이네……","recordingScript":"","memo":"음성 175","voice":"","phaseId":"end01h-P1"},
{"rowNumber":177,"id":"end01h.mes#46145","kind":"text","speaker":"안리","english":"","japanese":"杏里「……は、はい……このままじゃ、ともくんの赤ちゃんが出てくる時、窮屈で可哀相……」","korean":"……네, 네…… 이대로면 토모 군 아기가 나올 때 좁아서 불쌍하잖아요……","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":178,"id":"end01h.mes#46598","kind":"text","speaker":"안리","english":"","japanese":"杏里「だから……もっともっと……ともくんの太くて硬いオチンチンで、私の中を柔らかく解してください……」","korean":"그러니까…… 더, 더…… 토모 군의 굵고 단단한 자지로 제 안을 부드럽게 풀어 주세요……","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":179,"id":"end01h.mes#46782","kind":"text","speaker":"나레이션","english":"","japanese":"ペニスによる蜜壷の矯正要望を受け、肉棒はキツい膣内をものともせずムクムクとその膨らみを増させていく。","korean":"성기로 질 안을 풀어 달라는 부탁에 꽉 조이는 것도 아랑곳하지 않고 성기가 더욱 부풀었다.","recordingScript":"","memo":"음성 178","voice":"","phaseId":"end01h-P1"},
{"rowNumber":180,"id":"end01h.mes#46964","kind":"text","speaker":"토모키","english":"","japanese":"大樹「……ああ、任せておけ！」","korean":"……그래, 맡겨 둬!","recordingScript":"","memo":"음성 179","voice":"","phaseId":"end01h-P1"},
{"rowNumber":181,"id":"end01h.mes#47076","kind":"text","speaker":"나레이션","english":"","japanese":"杏里の望みを叶える為に大きく傘の開いた亀頭で、俺はキツく滑る壁を押し広げるように擦り始めた。","korean":"안리가 바라는 대로 넓게 부푼 귀두로 꽉 조이는 미끈한 질벽을 벌리듯 문지르기 시작했다.","recordingScript":"","memo":"음성 180","voice":"","phaseId":"end01h-P1"},
{"rowNumber":182,"id":"end01h.mes#47595","kind":"text","speaker":"안리","english":"","japanese":"杏里「ふあぁ……ああっ！　はあっ、はあぁ！　あっ！　あっ！　はあぁ！」","korean":"하아…… 아앗! 하앗, 하아! 앗! 앗! 하아!","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":183,"id":"end01h.mes#47865","kind":"text","speaker":"안리","english":"","japanese":"杏里「ああっ！　……ともくん……ひ、広がる……おちんちん……気持ちいいぃ……」","korean":"아앗! ……토모 군…… 버, 벌어져요…… 자지가…… 기분 좋아요오……","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":184,"id":"end01h.mes#48025","kind":"text","speaker":"나레이션","english":"","japanese":"キツイ締まりに負けじと杏里の上体が揺れるほど激しく腰を打ち付け、水音を鳴り響かせて蜜壷を拡張する。","korean":"꽉 조이는 힘에 밀리지 않으려고 안리의 상체가 흔들릴 만큼 힘차게 허리를 부딪쳤다. 질척이는 물소리가 울리는 사이 질이 벌어졌다.","recordingScript":"","memo":"음성 183","voice":"","phaseId":"end01h-P1"},
{"rowNumber":185,"id":"end01h.mes#48323","kind":"text","speaker":"안리","english":"","japanese":"杏里「はぁっ……ふうっ、はっ、あっ！　ああっ！　……ふぅ、はぁ！」","korean":"하앗…… 후우, 하앗, 앗! 아앗! ……후우, 하아!","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":186,"id":"end01h.mes#48589","kind":"text","speaker":"시에","english":"","japanese":"紫衣「ふふ……杏里ったら……いやらしい顔しちゃって……」","korean":"후후…… 안리도 참…… 야한 얼굴을 하고 있네……","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":187,"id":"end01h.mes#48867","kind":"text","speaker":"나레이션","english":"","japanese":"興奮に汗ばむ杏里の背中にスッと紫衣の手が伸びると、白く細い指がきめ細やかな肌をこね回し始めた。","korean":"시에가 흥분으로 땀이 밴 안리의 등에 손을 뻗었다. 하얗고 가는 손가락이 고운 피부를 주무르기 시작했다.","recordingScript":"","memo":"음성 186","voice":"","phaseId":"end01h-P1"},
{"rowNumber":188,"id":"end01h.mes#49161","kind":"text","speaker":"시에","english":"","japanese":"紫衣「ふふ……こんなに身体を熱く濡らして……今どんな風に中を突かれてるの？」","korean":"후후…… 이렇게 몸이 뜨겁고 흠뻑 젖어서…… 지금 안쪽이 어떻게 느껴져?","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":189,"id":"end01h.mes#49437","kind":"text","speaker":"안리","english":"","japanese":"杏里「……んんっ！　んはぁ……ふ、太い……大きいオチンチンが……膣内をどんどん広げて……」","korean":"……으응! 하아…… 구, 굵고…… 큰 자지가…… 질 안을 자꾸 벌리고……","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":190,"id":"end01h.mes#49727","kind":"text","speaker":"안리","english":"","japanese":"杏里「熱くぬるぬると……少し乱暴な感じで……んあっ！　……擦り付けられて……とても、気持ちいいです……」","korean":"뜨겁고 미끈하게…… 조금 거친 듯이…… 아앗! ……문질러져서…… 정말 기분 좋아요……","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":191,"id":"end01h.mes#50171","kind":"text","speaker":"시에","english":"","japanese":"紫衣「大樹……少し、らしいわよ？」","korean":"토모키…… 조금이라는데?","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":192,"id":"end01h.mes#50287","kind":"text","speaker":"토모키","english":"","japanese":"大樹「む、むぅ？」","korean":"으, 음?","recordingScript":"","memo":"음성 191","voice":"","phaseId":"end01h-P1"},
{"rowNumber":193,"id":"end01h.mes#50505","kind":"text","speaker":"시에","english":"","japanese":"紫衣「そんなヌルい腰の振り方なんてせず……ほら、私ごと犯す気持ちで、杏里を突いてあげなさい！」","korean":"그렇게 시시하게 허리만 움직이지 말고…… 자, 나까지 범한다는 생각으로 안리를 찔러 줘!","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":194,"id":"end01h.mes#50681","kind":"text","speaker":"토모키","english":"","japanese":"大樹「ああ、まかせろ！」","korean":"그래, 맡겨 둬!","recordingScript":"","memo":"음성 193","voice":"","phaseId":"end01h-P1"},
{"rowNumber":195,"id":"end01h.mes#50787","kind":"text","speaker":"나레이션","english":"","japanese":"腰を掴みなおすと……俺は二人まとめてペニスを突き入れる気持ちで、激しく腰を振り始めた。","korean":"허리를 다시 붙잡고…… 두 사람에게 한꺼번에 성기를 밀어 넣는다는 기세로 거칠게 허리를 움직이기 시작했다.","recordingScript":"","memo":"음성 194","voice":"","phaseId":"end01h-P1"},
{"rowNumber":196,"id":"end01h.mes#51338","kind":"text","speaker":"안리","english":"","japanese":"杏里「はあっ！　はげっ、しいぃ！　……ああっ！　んんっ！　んはぁ！」","korean":"하앗! 너, 너무 세요오! ……아앗! 으응! 하아!","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":197,"id":"end01h.mes#51606","kind":"text","speaker":"안리","english":"","japanese":"杏里「ああぁん！　……ともくん！　んはぁ！　い、いいっ！　おまんこ気持ちいい！　はあぁ、ああっ、突いてぇ……ああっ、強くっ！　ふうっ！　はっ！　あぁ！！」","korean":"아아앙! ……토모 군! 하아! 조, 좋아요! 보지가 기분 좋아요! 하아, 아앗, 찔러 줘요…… 아앗, 더 세게! 후우! 하앗! 아아!!","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":198,"id":"end01h.mes#51842","kind":"text","speaker":"나레이션","english":"","japanese":"杏里は感じるたび色香を増し、蜜壷は肉棒を締める力を強めていく。","korean":"느낄 때마다 안리는 더 요염해졌고 질이 성기를 더 세게 조였다.","recordingScript":"","memo":"음성 197","voice":"","phaseId":"end01h-P1"},
{"rowNumber":199,"id":"end01h.mes#51986","kind":"text","speaker":"나레이션","english":"","japanese":"その狭い膣とペニスから生まれる摩擦が猛烈な刺激となり、目の前を白く霞ませる。","korean":"좁은 질에 성기가 쓸려 강렬한 자극이 번졌다. 눈앞이 하얗게 흐려졌다.","recordingScript":"","memo":"음성 198","voice":"","phaseId":"end01h-P1"},
{"rowNumber":200,"id":"end01h.mes#52262","kind":"text","speaker":"안리","english":"","japanese":"杏里「はぁ！　ああっ！　はあぁ！　熱っ、熱いのが昇って……はぁ！　あ、頭が……弾けるっ！」","korean":"하아! 아앗! 하아! 뜨, 뜨거운 게 올라와서…… 하아! 머, 머리가 터질 것 같아요!","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":201,"id":"end01h.mes#52552","kind":"text","speaker":"시에","english":"","japanese":"紫衣「ふふ……普段のおすまし顔なんかより……ずっと可愛いわ、杏里……」","korean":"후후…… 평소에 새침하게 있던 얼굴보다…… 훨씬 귀여워, 안리……","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":202,"id":"end01h.mes#52962","kind":"text","speaker":"안리","english":"","japanese":"杏里「紫衣お姉様ぁ……わっ、私……もっ……もおぉ！　……いっ……イク、イクぅ！」","korean":"시에 언니이…… 저, 저…… 이, 이제에! ……가…… 가요, 가요오!","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":203,"id":"end01h.mes#53242","kind":"text","speaker":"시에","english":"","japanese":"紫衣「さぁ、イキなさい……私に……貴方が恥じらいもなくイク顔を……見せなさい！」","korean":"자, 가 버려…… 부끄러워하지 말고, 가는 얼굴을 나한테 보여 줘!","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":204,"id":"end01h.mes#53522","kind":"text","speaker":"안리","english":"","japanese":"杏里「は、はいっ！　んはぁ！　あふぅ、あっ、ああっ、あぁん！　いいっ、気持ちいいっ！」","korean":"네, 네! 하아! 후우, 앗, 아앗, 아앙! 좋아요, 기분 좋아요!","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":205,"id":"end01h.mes#53808","kind":"text","speaker":"안리","english":"","japanese":"杏里「んはっ、んあぁ……ともくんのおちんちんに、おまんこいっぱい擦られて……擦られてぇ……」","korean":"하앗, 아아…… 토모 군 자지에 보지가 잔뜩 쓸려서…… 자꾸 쓸려서……","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":206,"id":"end01h.mes#54100","kind":"text","speaker":"안리","english":"","japanese":"杏里「ああっ、く、来る……あぁっ！　……イクッ、イクッ、イクッ！　イクッ！！」","korean":"아앗, 오, 와요…… 아앗! ……가요, 가요, 가요! 가요!!","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":207,"id":"end01h.mes#54378","kind":"text","speaker":"안리","english":"","japanese":"杏里「イクうううぅぅぅうううぅぅぅうううう！！！」","korean":"가아아아아아아아!!!","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":208,"id":"end01h.mes#54548","kind":"text","speaker":"나레이션","english":"","japanese":"絶頂と共に一段と締まりを見せた蜜壷から勢いよくペニスを引き抜くと、俺は先端まで込み上げていた粘液をビクビクと吐き出させた。","korean":"절정과 함께 더 세게 조여 오는 질에서 성기를 단숨에 뺐다. 끝까지 치밀어 오른 정액을 움찔거리며 쏟았다.","recordingScript":"","memo":"음성 207","voice":"","phaseId":"end01h-P1"},
{"rowNumber":209,"id":"end01h.mes#55105","kind":"text","speaker":"안리","english":"","japanese":"杏里「はあっ！　はあっ！　あっ！　……んはあっ！　ふぅ！　はあぁ……」","korean":"하앗! 하앗! 앗! ……하아앗! 후우! 하아……","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":210,"id":"end01h.mes#55257","kind":"text","speaker":"나레이션","english":"","japanese":"膣のキツい締め付けから開放された肉棒から欲望が噴出され、抱き合う二人の身体へ次々と熱い粘液を吹きかけていく。","korean":"꽉 조이던 질에서 벗어난 성기에서 욕망이 터져 나와 서로를 껴안은 두 사람의 몸에 뜨거운 정액이 연달아 튀었다.","recordingScript":"","memo":"음성 209","voice":"","phaseId":"end01h-P1"},
{"rowNumber":211,"id":"end01h.mes#55565","kind":"text","speaker":"안리","english":"","japanese":"杏里「はあ、はぁ……ふぅう……はあ……あふぅう……」","korean":"하아, 하아…… 후우우…… 하아…… 후우우……","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":212,"id":"end01h.mes#55817","kind":"text","speaker":"시에","english":"","japanese":"紫衣「ふふ……相変わらず匂いも勢いも凄いものね……折角だし、杏里に塗ってあげようかしら」","korean":"후후…… 냄새도 기세도 여전하네…… 이왕 이렇게 된 거 안리한테 발라 줄까.","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":213,"id":"end01h.mes#56272","kind":"text","speaker":"안리","english":"","japanese":"杏里「紫衣お姉様……お姉様にも……ともくんの精液……んんっ！　……塗ってあげますね……」","korean":"시에 언니…… 언니한테도 토모 군 정액을…… 으응! ……발라 줄게요……","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":214,"id":"end01h.mes#56856","kind":"text","speaker":"나레이션","english":"","japanese":"身体に撒き散らされた精液を、擦り合う淫らな紫衣と杏里……","korean":"시에와 안리는 몸에 튄 정액을 서로의 몸에 야릇하게 문질렀다……","recordingScript":"","memo":"음성 213","voice":"","phaseId":"end01h-P1"},
{"rowNumber":215,"id":"end01h.mes#56994","kind":"text","speaker":"나레이션","english":"","japanese":"その二人の姿を横目にベッドへ投げ出すように身体を沈めると……俺は暫しの休憩を取る事に決めた。","korean":"그 모습을 곁눈질하며 침대에 몸을 던지듯 누웠다…… 잠시 쉬기로 했다.","recordingScript":"","memo":"음성 214","voice":"","phaseId":"end01h-P1"},
{"rowNumber":216,"id":"end01h.mes#57666","kind":"text","speaker":"나레이션","english":"","japanese":"俺が疲弊した身体を休め、活力を取り戻す中……","korean":"내가 지친 몸을 쉬고 기운을 되찾는 사이……","recordingScript":"","memo":"음성 216","voice":"","phaseId":"end01h-P1"},
{"rowNumber":217,"id":"end01h.mes#58221","kind":"text","speaker":"나레이션","english":"","japanese":"二人は休む事なく、摺り寄せた陰唇からヌチャヌチャと卑猥な音を立て、快感に震える肢体を俺の前へ晒し続けていた。","korean":"둘은 쉴 새 없이 음순을 맞비비며 질척이는 소리를 냈다. 쾌감에 떠는 몸을 내 앞에 그대로 드러냈다.","recordingScript":"","memo":"음성 217","voice":"","phaseId":"end01h-P1"},
{"rowNumber":218,"id":"end01h.mes#58529","kind":"text","speaker":"안리","english":"","japanese":"杏里「んっ……んちゅっ……れろっ……はむっ……」","korean":"으응…… 쪽…… 핥짝…… 앙……","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":219,"id":"end01h.mes#58777","kind":"text","speaker":"시에","english":"","japanese":"紫衣「れろっ……ちゅぅ……ちゅばっ……はあぁ……」","korean":"핥짝…… 쮸우…… 쪽…… 하아……","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":220,"id":"end01h.mes#59027","kind":"text","speaker":"안리","english":"","japanese":"杏里「ちゅぶっ、んちゅぅ……はむっ、れろっ……ちゅぶっ、ちゅっ……」","korean":"쪽, 쮸우…… 앙, 핥짝…… 쪽, 쪽……","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":221,"id":"end01h.mes#59295","kind":"text","speaker":"시에","english":"","japanese":"紫衣「はむっ、んふぅ……ちゅっ、れろっ、んちゅっ……ちゅばっ、んちゅっ……」","korean":"앙, 후우…… 쪽, 핥짝, 쪽…… 쪽, 쪽……","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":222,"id":"end01h.mes#59453","kind":"text","speaker":"나레이션","english":"","japanese":"恋人同士に見えるほどの濃厚なキスの応酬……","korean":"연인처럼 깊은 입맞춤이 이어졌다……","recordingScript":"","memo":"음성 222","voice":"","phaseId":"end01h-P1"},
{"rowNumber":223,"id":"end01h.mes#59577","kind":"text","speaker":"나레이션","english":"","japanese":"二人の美女の絡み合う姿を見て、肉棒が休憩は終わりだとムクムクと力を取り戻していく。","korean":"두 미녀가 몸을 얽는 걸 보자 쉴 만큼 쉬었다는 듯 성기에 다시 힘이 들어갔다.","recordingScript":"","memo":"음성 223","voice":"","phaseId":"end01h-P1"},
{"rowNumber":224,"id":"end01h.mes#59859","kind":"text","speaker":"안리","english":"","japanese":"杏里「ちゅぶっ、んちゅぅ、んちゅぅうぅ……んはぁ……？」","korean":"쪽, 쮸우, 쮸우우…… 하아……?","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":225,"id":"end01h.mes#60255","kind":"text","speaker":"안리","english":"","japanese":"杏里「あ……ともくん……おちんちんの休憩は終わりですか？」","korean":"아…… 토모 군…… 자지는 이제 다 쉬었어요?","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":226,"id":"end01h.mes#60395","kind":"text","speaker":"토모키","english":"","japanese":"大樹「ああ、もう十分だ……」","korean":"응, 충분히 쉬었어……","recordingScript":"","memo":"음성 226","voice":"","phaseId":"end01h-P1"},
{"rowNumber":227,"id":"end01h.mes#60623","kind":"text","speaker":"안리","english":"","japanese":"杏里「……では、今度は私の中に……ともくんの熱い精液を出してください……」","korean":"……그럼 이번에는 제 안에…… 토모 군의 뜨거운 정액을 싸 주세요……","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":228,"id":"end01h.mes#60897","kind":"text","speaker":"시에","english":"","japanese":"紫衣「そういえば杏里はまだだったわね……でも、貴方だけするのは私がつまらないわ」","korean":"그러고 보니 안리는 아직이었지…… 그래도 너만 하면 난 재미없어.","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":229,"id":"end01h.mes#61177","kind":"text","speaker":"안리","english":"","japanese":"杏里「なら、今度は交互に突いてもらいましょう」","korean":"그럼 이번에는 번갈아서 찔러 달라고 해요.","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":230,"id":"end01h.mes#61423","kind":"text","speaker":"시에","english":"","japanese":"紫衣「……いいアイデアね、流石私の妹……さぁ大樹……次は、交互に突いて……私達を一緒に感じさせて……」","korean":"……좋은 생각이네, 역시 내 동생이야…… 자, 토모키…… 이번에는 번갈아서 찔러 줘. 우리 둘 다 느끼게 해 줘……","recordingScript":"","memo":"","voice":"","phaseId":"end01h-P1"},
{"rowNumber":231,"id":"end01h.mes#61607","kind":"text","speaker":"나레이션","english":"","japanese":"淫らな熱を帯びた二人の雌の視線は、雄の本能を強く呼び起こし……","korean":"달아오른 두 사람의 시선이 내 본능을 세게 깨웠다……","recordingScript":"","memo":"음성 231","voice":"","phaseId":"end01h-P1"},
{"rowNumber":232,"id":"end01h.mes#61805","kind":"text","speaker":"나레이션","english":"","japanese":"俺は興奮も露わに……むせ返るような女の体臭を放つ紫衣と杏里の肢体へ……ゆっくりと手を伸ばした。","korean":"흥분을 감추지 못한 채…… 숨이 막힐 만큼 짙은 체취를 풍기는 시에와 안리의 몸에 천천히 손을 뻗었다.","recordingScript":"","memo":"음성 232","voice":"","phaseId":"end01h-P1"}
];
